use open_sdbl::metadata::{Value,inflate_raw_deflate,parse_serialized};
use std::{fs,path::Path,error::Error,collections::BTreeMap};
fn list(v:&Value)->Option<&[Value]>{if let Value::List(v)=v{Some(v)}else{None}}
fn text(v:&Value)->Option<&str>{match v{Value::Atom(s)|Value::String(s)=>Some(s),_=>None}}
fn string(v:&Value)->Option<&str>{if let Value::String(s)=v{Some(s)}else{None}}
fn at<'a>(v:&'a Value,p:&[usize])->Option<&'a Value>{p.iter().try_fold(v,|v,i|list(v)?.get(*i))}
fn shape(v:Option<&Value>)->String{v.and_then(list).map_or("?".into(),|v|format!("{}/{}",v.first().and_then(text).unwrap_or("?"),v.len()))}
fn run()->Result<(),Box<dyn Error>>{let args=std::env::args().collect::<Vec<_>>();println!("owner\tname\towner_comment_len\towner_flags\tmember_shapes\tnonempty_member_comments\tnonzero_member_identity_flags\tempty_patterns");for row in fs::read_to_string(&args[1])?.lines().skip(1){let c=row.split('\t').collect::<Vec<_>>();if c[3]!="38"||c[7]!="None"{continue;}let tree=parse_serialized(&inflate_raw_deflate(&fs::read(Path::new(&args[2]).join(c[0]))?)?)?;let h=at(&tree,&[1,9,1]).and_then(list).unwrap();let comment=h.get(4).and_then(string).map_or("nonstring".into(),|s|s.len().to_string());let flags=h.iter().skip(5).map(|v|text(v).unwrap_or("?")).collect::<Vec<_>>().join(",");let mut shapes=BTreeMap::<String,usize>::new();let(mut comments,mut idflags,mut empty)=(0,0,0);for group in list(&tree).unwrap(){let Some(g)=list(group)else{continue};if g.first().and_then(text)!=Some("45e46cbc-3e24-4165-8b7b-cc98a6f80211"){continue;}for r in g.iter().skip(2){let key=format!("w{}:b{}:i{}",shape(at(r,&[0])),shape(at(r,&[0,1])),shape(at(r,&[0,1,1,1])));*shapes.entry(key).or_default()+=1;if let Some(i)=at(r,&[0,1,1,1]).and_then(list){if i.get(4).and_then(string).is_some_and(|s|!s.is_empty()){comments+=1;}if i.iter().skip(5).any(|v|text(v)!=Some("0")){idflags+=1;}}if at(r,&[0,1,1,2]).and_then(list).is_some_and(|p|p.len()==1&&p.first().and_then(string)==Some("Pattern")){empty+=1;}}}println!("{}\t{}\t{}\t{}\t{}\t{}\t{}\t{}",c[0],c[1],comment,flags,shapes.into_iter().map(|(s,n)|format!("{s}={n}")).collect::<Vec<_>>().join(";"),comments,idflags,empty);}Ok(())}
fn main(){if let Err(e)=run(){eprintln!("ERROR:{e}");std::process::exit(1)}}
